// Kiro's balance reflex: step into a sudden lateral push.
// Body-frame lateral velocity is compared with a slow moving average; a jump beyond a dead band
// (0.15 m/s) is answered with a lateral command in the same direction, capped at 0.6 m/s.
import { Reflex, type ReflexState } from './reflex.js';

const DEAD_BAND = 0.15; // m/s
const GAIN = 0.6; // (m/s) of command per (m/s) of velocity jump
const CAP = 0.6; // m/s
const EMA = 0.05; // per Control_Step (20 ms)

export class KiroReflex extends Reflex {
  private vyAvg = 0;

  override reset(): void { this.vyAvg = 0; }

  override command(s: ReflexState, base: ArrayLike<number>, out: Float64Array): void {
    const q = s.qpos, v = s.qvel;
    const w = q[3] as number, x = q[4] as number, y = q[5] as number, z = q[6] as number;
    const yaw = Math.atan2(2 * (w * z + x * y), 1 - 2 * (y * y + z * z));
    const vyBody = -Math.sin(yaw) * (v[0] as number) + Math.cos(yaw) * (v[1] as number);
    const dev = vyBody - this.vyAvg;
    this.vyAvg += EMA * dev;
    out[0] = base[0] as number;
    out[1] = base[1] as number;
    out[2] = base[2] as number;
    if (Math.abs(dev) > DEAD_BAND) {
      const add = Math.max(-CAP, Math.min(CAP, GAIN * dev));
      out[1] = Math.max(-CAP, Math.min(CAP, (base[1] as number) + add));
    }
  }
}

